// BTI fix
altera_std_synchronizer_nocut ninit_done_free_run_sync_inst (.clk (free_run_clk), .reset_n (~ninit_done), .din (1'b1), .dout (ninit_done_free_run_sync) );

// BTI fix assign pin_perst_n_o = hrc_pin_perst_n;
assign pin_perst_n_o = ch13_hdpldadapt_pld_fpll_shared_direct_async_out;

assign coreclkout_hip = PIPED_FULL? 1'b0 : (PIPED_HYBRID? ch4_hdpldadapt_pld_pcs_tx_clk_out1_dcm : ch15_hdpldadapt_pld_pcs_tx_clk_out1_dcm);

// BTI fix assign hrc_pin_perst_n             = ch13_hdpldadapt_pld_fpll_shared_direct_async_out;
altera_std_synchronizer_nocut pin_perst_n_sync  (.clk (free_run_clk), .reset_n (ninit_done_free_run_sync), .din (ch13_hdpldadapt_pld_fpll_shared_direct_async_out), .dout (hrc_pin_perst_n) );

wire  pld_fullrst_n;
generate
   if (qhip_silicon_revc_hwtcl) begin
      if (hssi_ctr_independent_pcie_x8x8 == "enable") begin: A //2x8 indpendent perst is still supported
          assign hrc_pin_perst0_n          = 1'b1;
          // BTI fix assign hrc_pin_perst1_n          = pld_fullrst_n;
          altera_std_synchronizer_nocut pin_perst1_n_sync  (.clk (free_run_clk), .reset_n (ninit_done_free_run_sync), .din (pld_fullrst_n), .dout (hrc_pin_perst1_n) );
      end else if (hssi_ctr_true_independent_support_mode == "enable") begin: B
          // BTI fix assign hrc_pin_perst0_n          = ch17_hdpldadapt_pld_tx_hssi_fifo_latency_pulse;
          // BTI fix assign hrc_pin_perst1_n          = ch17_hdpldadapt_pld_tx_hssi_fifo_latency_pulse//nwai: ;
          altera_std_synchronizer_nocut pin_perst0_n_sync  (.clk (free_run_clk), .reset_n (ninit_done_free_run_sync), .din (ch17_hdpldadapt_pld_rx_hssi_fifo_latency_pulse), .dout (hrc_pin_perst0_n) );
          altera_std_synchronizer_nocut pin_perst1_n_sync  (.clk (free_run_clk), .reset_n (ninit_done_free_run_sync), .din (ch17_hdpldadapt_pld_tx_hssi_fifo_latency_pulse), .dout (hrc_pin_perst1_n) );
      end else begin
          assign hrc_pin_perst0_n          = 1'b1;
          assign hrc_pin_perst1_n          = 1'b1;
      end
   end else begin: C // In RNRA0 and B0, ch17_hdpldadapt_pld_t/rx_hssi_fifo_latency_pulse is reserved bit with 1'b0
      assign hrc_pin_perst0_n          = 1'b1;
      // BTI fix assign hrc_pin_perst1_n          = (hssi_ctr_independent_pcie_x8x8=="enable") ? pld_fullrst_n : 1'b1;
      if (hssi_ctr_independent_pcie_x8x8=="enable") begin : D
         altera_std_synchronizer_nocut pin_perst1_n_sync  (.clk (free_run_clk), .reset_n (ninit_done_free_run_sync), .din (pld_fullrst_n), .dout (hrc_pin_perst1_n) );
      end
      else begin
         assign hrc_pin_perst1_n = 1'b1;
      end
   end
endgenerate

