    end
    else begin : g_p1_user_avmm_warm_rst_rdy_inactive
      assign p1_user_avmm_warm_rst_rdy = 1'b0;
    end

    if (!qhip_csb2wire_en_hwtcl) begin : g_p2_user_avmm_warm_rst_rdy_tie_off
      assign p2_user_avmm_warm_rst_rdy = 1'b1;
    end
    else if (EHP2) begin : g_p2_user_avmm_warm_rst_rdy_sync
