    end
    else begin : g_p2_user_avmm_warm_rst_rdy_inactive
      assign p2_user_avmm_warm_rst_rdy = 1'b0;
    end
    
    if (!qhip_csb2wire_en_hwtcl) begin : g_p3_user_avmm_warm_rst_rdy_tie_off
      assign p3_user_avmm_warm_rst_rdy = 1'b1;
    end
    else if (EHP3) begin : g_p3_user_avmm_warm_rst_rdy_sync
      altera_std_synchronizer_nocut p3_user_avmm_warm_rst_rdy_sync_inst ( .clk (coreclkout_hip), .reset_n (ninit_done_sync), .din (p3_user_avmm_warm_rst_rdy_w), .dout (p3_user_avmm_warm_rst_rdy) );
    end
    else begin : g_p3_user_avmm_warm_rst_rdy_inactive
      assign p3_user_avmm_warm_rst_rdy = 1'b0;
    end
endgenerate

