//-------------------------------------------------  Synchronizers  ---------------------------------------------
wire	ch0_11_maib_sync_rst_n;
wire	ch12_23_maib_sync_rst_n;

wire [PIPED_WIDTH-1:0]	pipe_direct_pld_pcs_rst_n;
wire [PIPED_WIDTH-1:0]	pipe_direct_pld_pcs_rst_n_sync;
reg  [PIPED_WIDTH-1:0]	pipe_direct_pld_pcs_rst_n_gated;
wire	pipe_direct_pld_pcs_rst_n_gated_unpacked [PIPED_WIDTH-1:0];

assign ch0_11_maib_sync_rst_n  = PIPED_FULL? ninit_done_sync_piped : ninit_done_sync;
assign ch12_23_maib_sync_rst_n = (PIPED_FULL || PIPED_HYBRID)? ninit_done_sync_piped : ninit_done_sync;

genvar i;
generate
	if(hssi_ctr_topology == "pipe_direct_pcie_x8" || hssi_ctr_topology == "pipe_direct_pcie_x4x4") begin
		for (i=0; i<12 ;i++) begin : rx_transfer_sync_pcie
			altera_std_synchronizer_nocut rx_transfer_en_sync_inst (
    	            		.clk		(ch4_hdpldadapt_pld_pcs_tx_clk_out1_dcm),
    	            		.reset_n	(ch0_11_maib_sync_rst_n),
    	            		.din		(aib_pld_hssi_rx_transfer_en[i]),
    	            		.dout		(aib_pld_hssi_rx_transfer_en_sync[i])
    	    	);
		end
		for (i=12; i<24 ;i++) begin : rx_transfer_sync_piped
			altera_std_synchronizer_nocut rx_transfer_en_sync_inst (
    	            		.clk		(ch15_hdpldadapt_pld_pcs_tx_clk_out1_dcm),
    	            		.reset_n	(ch12_23_maib_sync_rst_n),
    	            		.din		(aib_pld_hssi_rx_transfer_en[i]),
    	            		.dout		(aib_pld_hssi_rx_transfer_en_sync[i])
    	   	);
		end
	end
	else begin
		for (i=0;i<24;i++) begin : rx_transfer_sync
			altera_std_synchronizer_nocut rx_transfer_en_sync_inst (
    	            		.clk		(ch15_hdpldadapt_pld_pcs_tx_clk_out1_dcm),
    	            		.reset_n	(ch0_11_maib_sync_rst_n),
    	            		.din		(aib_pld_hssi_rx_transfer_en[i]),
    	            		.dout		(aib_pld_hssi_rx_transfer_en_sync[i])
    	    	);
		end
	end

	if (PIPED_FULL) begin
		wire [15:0] pipe_full_tx_transfer_en;	
		wire [15:0] pipe_full_tx_transfer_en_sync;	
		assign pipe_direct_tx_transfer_en_sync = {
		   pipe_full_tx_transfer_en_sync[15], pipe_full_tx_transfer_en_sync[14],
		   pipe_full_tx_transfer_en_sync[13], pipe_full_tx_transfer_en_sync[12],
		   pipe_full_tx_transfer_en_sync[11], pipe_full_tx_transfer_en_sync[10],
		   pipe_full_tx_transfer_en_sync[9], pipe_full_tx_transfer_en_sync[8],
		   pipe_full_tx_transfer_en_sync[7], pipe_full_tx_transfer_en_sync[6],
		   pipe_full_tx_transfer_en_sync[5], pipe_full_tx_transfer_en_sync[4],
		   pipe_full_tx_transfer_en_sync[3], pipe_full_tx_transfer_en_sync[2],
		   pipe_full_tx_transfer_en_sync[1], pipe_full_tx_transfer_en_sync[0]
		};

		assign pipe_full_tx_transfer_en[0] = aib_pld_fabric_tx_transfer_en[2];
		assign pipe_full_tx_transfer_en[1] = aib_pld_fabric_tx_transfer_en[3];
		assign pipe_full_tx_transfer_en[2] = aib_pld_fabric_tx_transfer_en[4];
		assign pipe_full_tx_transfer_en[3] = aib_pld_fabric_tx_transfer_en[5];
		assign pipe_full_tx_transfer_en[4] = aib_pld_fabric_tx_transfer_en[6];
		assign pipe_full_tx_transfer_en[5] = aib_pld_fabric_tx_transfer_en[7];
		assign pipe_full_tx_transfer_en[6] = aib_pld_fabric_tx_transfer_en[8];
		assign pipe_full_tx_transfer_en[7] = aib_pld_fabric_tx_transfer_en[9];
		assign pipe_full_tx_transfer_en[8] = aib_pld_fabric_tx_transfer_en[15];
		assign pipe_full_tx_transfer_en[9] = aib_pld_fabric_tx_transfer_en[16];
		assign pipe_full_tx_transfer_en[10] = aib_pld_fabric_tx_transfer_en[17];
		assign pipe_full_tx_transfer_en[11] = aib_pld_fabric_tx_transfer_en[18];
		assign pipe_full_tx_transfer_en[12] = aib_pld_fabric_tx_transfer_en[19];
		assign pipe_full_tx_transfer_en[13] = aib_pld_fabric_tx_transfer_en[20];
		assign pipe_full_tx_transfer_en[14] = aib_pld_fabric_tx_transfer_en[21];
		assign pipe_full_tx_transfer_en[15] = aib_pld_fabric_tx_transfer_en[22];
		assign ln0_pipe_direct_tx_transfer_en_o = pipe_full_tx_transfer_en_sync[0];
		assign ln1_pipe_direct_tx_transfer_en_o = pipe_full_tx_transfer_en_sync[1];
		assign ln2_pipe_direct_tx_transfer_en_o = pipe_full_tx_transfer_en_sync[2];
		assign ln3_pipe_direct_tx_transfer_en_o = pipe_full_tx_transfer_en_sync[3];
		assign ln4_pipe_direct_tx_transfer_en_o = pipe_full_tx_transfer_en_sync[4];
		assign ln5_pipe_direct_tx_transfer_en_o = pipe_full_tx_transfer_en_sync[5];
		assign ln6_pipe_direct_tx_transfer_en_o = pipe_full_tx_transfer_en_sync[6];
		assign ln7_pipe_direct_tx_transfer_en_o = pipe_full_tx_transfer_en_sync[7];
		assign ln8_pipe_direct_tx_transfer_en_o = pipe_full_tx_transfer_en_sync[8];
		assign ln9_pipe_direct_tx_transfer_en_o = pipe_full_tx_transfer_en_sync[9];
		assign ln10_pipe_direct_tx_transfer_en_o = pipe_full_tx_transfer_en_sync[10];
		assign ln11_pipe_direct_tx_transfer_en_o = pipe_full_tx_transfer_en_sync[11];
		assign ln12_pipe_direct_tx_transfer_en_o = pipe_full_tx_transfer_en_sync[12];
		assign ln13_pipe_direct_tx_transfer_en_o = pipe_full_tx_transfer_en_sync[13];
		assign ln14_pipe_direct_tx_transfer_en_o = pipe_full_tx_transfer_en_sync[14];
		assign ln15_pipe_direct_tx_transfer_en_o = pipe_full_tx_transfer_en_sync[15];

		for (i=0; i<16 ;i++) begin : full_tx_transfer_sync_pipe
                        altera_std_synchronizer_nocut pipe_full_tx_transfer_en_sync_inst (
                                .clk            (pipe_direct_pld_tx_clk_out_o),
				// nwai: CDC fix 
                                .reset_n        (ninit_done_sync_piped),
                                //Hanifi: revert back nwai fix        .reset_n        (pipe_direct_pld_pcs_rst_n_gated_unpacked[i]),
                                .din            (pipe_full_tx_transfer_en[i]),
                                .dout           (pipe_full_tx_transfer_en_sync[i])
                );
                end
	end

        if (PIPED_HYBRID) begin
                wire [7:0] pipe_hybrid_tx_transfer_en;
                wire [7:0] pipe_hybrid_tx_transfer_en_sync;
		assign pipe_direct_tx_transfer_en_sync = {
		   pipe_hybrid_tx_transfer_en_sync[7], pipe_hybrid_tx_transfer_en_sync[6],
		   pipe_hybrid_tx_transfer_en_sync[5], pipe_hybrid_tx_transfer_en_sync[4],
		   pipe_hybrid_tx_transfer_en_sync[3], pipe_hybrid_tx_transfer_en_sync[2],
		   pipe_hybrid_tx_transfer_en_sync[1], pipe_hybrid_tx_transfer_en_sync[0]
		};

                assign pipe_hybrid_tx_transfer_en[0] = aib_pld_fabric_tx_transfer_en[2];
                assign pipe_hybrid_tx_transfer_en[1] = aib_pld_fabric_tx_transfer_en[3];
                assign pipe_hybrid_tx_transfer_en[2] = aib_pld_fabric_tx_transfer_en[4];
                assign pipe_hybrid_tx_transfer_en[3] = aib_pld_fabric_tx_transfer_en[5];
                assign pipe_hybrid_tx_transfer_en[4] = aib_pld_fabric_tx_transfer_en[6];
                assign pipe_hybrid_tx_transfer_en[5] = aib_pld_fabric_tx_transfer_en[7];
                assign pipe_hybrid_tx_transfer_en[6] = aib_pld_fabric_tx_transfer_en[8];
                assign pipe_hybrid_tx_transfer_en[7] = aib_pld_fabric_tx_transfer_en[9];
                assign ln0_pipe_direct_tx_transfer_en_o = pipe_hybrid_tx_transfer_en_sync[0];
                assign ln1_pipe_direct_tx_transfer_en_o = pipe_hybrid_tx_transfer_en_sync[1];
                assign ln2_pipe_direct_tx_transfer_en_o = pipe_hybrid_tx_transfer_en_sync[2];
                assign ln3_pipe_direct_tx_transfer_en_o = pipe_hybrid_tx_transfer_en_sync[3];
                assign ln4_pipe_direct_tx_transfer_en_o = pipe_hybrid_tx_transfer_en_sync[4];
                assign ln5_pipe_direct_tx_transfer_en_o = pipe_hybrid_tx_transfer_en_sync[5];
                assign ln6_pipe_direct_tx_transfer_en_o = pipe_hybrid_tx_transfer_en_sync[6];
                assign ln7_pipe_direct_tx_transfer_en_o = pipe_hybrid_tx_transfer_en_sync[7];
		assign ln8_pipe_direct_tx_transfer_en_o = 1'b0;
		assign ln9_pipe_direct_tx_transfer_en_o = 1'b0;
		assign ln10_pipe_direct_tx_transfer_en_o = 1'b0;
		assign ln11_pipe_direct_tx_transfer_en_o = 1'b0;
		assign ln12_pipe_direct_tx_transfer_en_o = 1'b0;
		assign ln13_pipe_direct_tx_transfer_en_o = 1'b0;
		assign ln14_pipe_direct_tx_transfer_en_o = 1'b0;
		assign ln15_pipe_direct_tx_transfer_en_o = 1'b0;

                for (i=0; i<8 ;i++) begin : hybrid_tx_transfer_sync_pipe
                        altera_std_synchronizer_nocut pipe_hybrid_tx_transfer_en_sync_inst (
                                .clk            (pipe_direct_pld_tx_clk_out_o),
                                .reset_n        (ninit_done_sync_piped),
                                .din            (pipe_hybrid_tx_transfer_en[i]),
                                .dout           (pipe_hybrid_tx_transfer_en_sync[i])
                );
                end
        end

	if (!PIPED_HYBRID & !PIPED_FULL) begin
		assign pipe_direct_tx_transfer_en_sync[15] = 1'b1;
		assign pipe_direct_tx_transfer_en_sync[14] = 1'b1;
		assign pipe_direct_tx_transfer_en_sync[13] = 1'b1;
		assign pipe_direct_tx_transfer_en_sync[12] = 1'b1;
		assign pipe_direct_tx_transfer_en_sync[11] = 1'b1;
		assign pipe_direct_tx_transfer_en_sync[10] = 1'b1;
		assign pipe_direct_tx_transfer_en_sync[9] = 1'b1;
		assign pipe_direct_tx_transfer_en_sync[8] = 1'b1;
		assign pipe_direct_tx_transfer_en_sync[7] = 1'b1;
		assign pipe_direct_tx_transfer_en_sync[6] = 1'b1;
		assign pipe_direct_tx_transfer_en_sync[5] = 1'b1;
		assign pipe_direct_tx_transfer_en_sync[4] = 1'b1;
		assign pipe_direct_tx_transfer_en_sync[3] = 1'b1;
		assign pipe_direct_tx_transfer_en_sync[2] = 1'b1;
		assign pipe_direct_tx_transfer_en_sync[1] = 1'b1;
		assign pipe_direct_tx_transfer_en_sync[0] = 1'b1;

                assign ln0_pipe_direct_tx_transfer_en_o = 1'b0;
                assign ln1_pipe_direct_tx_transfer_en_o = 1'b0;
                assign ln2_pipe_direct_tx_transfer_en_o = 1'b0;
                assign ln3_pipe_direct_tx_transfer_en_o = 1'b0;
                assign ln4_pipe_direct_tx_transfer_en_o = 1'b0;
                assign ln5_pipe_direct_tx_transfer_en_o = 1'b0;
                assign ln6_pipe_direct_tx_transfer_en_o = 1'b0;
                assign ln7_pipe_direct_tx_transfer_en_o = 1'b0;
                assign ln8_pipe_direct_tx_transfer_en_o = 1'b0;
                assign ln9_pipe_direct_tx_transfer_en_o = 1'b0;
                assign ln10_pipe_direct_tx_transfer_en_o = 1'b0;
                assign ln11_pipe_direct_tx_transfer_en_o = 1'b0;
                assign ln12_pipe_direct_tx_transfer_en_o = 1'b0;
                assign ln13_pipe_direct_tx_transfer_en_o = 1'b0;
                assign ln14_pipe_direct_tx_transfer_en_o = 1'b0;
                assign ln15_pipe_direct_tx_transfer_en_o = 1'b0;
	end


	if(PIPED_HYBRID) begin
		assign pipe_direct_pld_pcs_rst_n = {ln15_pipe_direct_pld_pcs_rst_n_i, ln14_pipe_direct_pld_pcs_rst_n_i, 
						    ln13_pipe_direct_pld_pcs_rst_n_i, ln12_pipe_direct_pld_pcs_rst_n_i,
						    ln11_pipe_direct_pld_pcs_rst_n_i, ln10_pipe_direct_pld_pcs_rst_n_i,
						    ln9_pipe_direct_pld_pcs_rst_n_i,  ln8_pipe_direct_pld_pcs_rst_n_i};

		assign pipe_direct_pld_pcs_rst_n_gated_unpacked = '{pipe_direct_pld_pcs_rst_n_gated[7], pipe_direct_pld_pcs_rst_n_gated[6],  
							    	    pipe_direct_pld_pcs_rst_n_gated[5], pipe_direct_pld_pcs_rst_n_gated[4],
							    	    pipe_direct_pld_pcs_rst_n_gated[3], pipe_direct_pld_pcs_rst_n_gated[2],  
							    	    pipe_direct_pld_pcs_rst_n_gated[1], pipe_direct_pld_pcs_rst_n_gated[0]};
	end
	else begin
		assign pipe_direct_pld_pcs_rst_n = {ln15_pipe_direct_pld_pcs_rst_n_i, ln14_pipe_direct_pld_pcs_rst_n_i, 
						    ln13_pipe_direct_pld_pcs_rst_n_i, ln12_pipe_direct_pld_pcs_rst_n_i,
						    ln11_pipe_direct_pld_pcs_rst_n_i, ln10_pipe_direct_pld_pcs_rst_n_i,
						    ln9_pipe_direct_pld_pcs_rst_n_i,  ln8_pipe_direct_pld_pcs_rst_n_i,
						    ln7_pipe_direct_pld_pcs_rst_n_i,  ln6_pipe_direct_pld_pcs_rst_n_i, 
						    ln5_pipe_direct_pld_pcs_rst_n_i,  ln4_pipe_direct_pld_pcs_rst_n_i,
						    ln3_pipe_direct_pld_pcs_rst_n_i,  ln2_pipe_direct_pld_pcs_rst_n_i,
						    ln1_pipe_direct_pld_pcs_rst_n_i,  ln0_pipe_direct_pld_pcs_rst_n_i};

		assign pipe_direct_pld_pcs_rst_n_gated_unpacked = '{pipe_direct_pld_pcs_rst_n_gated[15], pipe_direct_pld_pcs_rst_n_gated[14],  
							    	    pipe_direct_pld_pcs_rst_n_gated[13], pipe_direct_pld_pcs_rst_n_gated[12],
							    	    pipe_direct_pld_pcs_rst_n_gated[11], pipe_direct_pld_pcs_rst_n_gated[10],  
							    	    pipe_direct_pld_pcs_rst_n_gated[9],  pipe_direct_pld_pcs_rst_n_gated[8],
							    	    pipe_direct_pld_pcs_rst_n_gated[7],  pipe_direct_pld_pcs_rst_n_gated[6],  
							    	    pipe_direct_pld_pcs_rst_n_gated[5],  pipe_direct_pld_pcs_rst_n_gated[4],
							    	    pipe_direct_pld_pcs_rst_n_gated[3],  pipe_direct_pld_pcs_rst_n_gated[2], 
							    	    pipe_direct_pld_pcs_rst_n_gated[1],  pipe_direct_pld_pcs_rst_n_gated[0]};
	end

	for(i=0; i<PIPED_WIDTH; i++) begin: sync_per_lane
	   altera_std_synchronizer_nocut pipe_direct_pld_pcs_rst_n_sync_inst (
	   	.clk 		(pipe_direct_pld_tx_clk_out_o), 
		.reset_n 	(ninit_done_sync_piped), 
		.din 		(pipe_direct_pld_pcs_rst_n[i]), 
		.dout 		(pipe_direct_pld_pcs_rst_n_gated[i]) 
	   );
	end

endgenerate

//------------------------------------  AIB Interface Mapping  --------------------------------------------------
generate
	for(i=0; i<12;i++) begin: aib_ch0_to_ch11_map
		assign hdpldadapt_pld_adapter_tx_pld_rst_n[i] = PIPED_FULL? piped_aib_pld_adapter_tx_pld_rst_n[i] : aib_pld_adapter_tx_pld_rst_n[i];
		assign hdpldadapt_pld_tx_dll_lock_req[i] = PIPED_FULL? piped_aib_pld_tx_dll_lock_req[i] : aib_pld_tx_dll_lock_req[i];
	end
	for(i=12; i<24;i++) begin: aib_ch12_to_ch24_map
		assign hdpldadapt_pld_adapter_tx_pld_rst_n[i] = PIPED_FULL? piped_aib_pld_adapter_tx_pld_rst_n[i] : PIPED_HYBRID? piped_aib_pld_adapter_tx_pld_rst_n[i-12] : aib_pld_adapter_tx_pld_rst_n[i];
		assign hdpldadapt_pld_tx_dll_lock_req[i] = PIPED_FULL? piped_aib_pld_tx_dll_lock_req[i] : PIPED_HYBRID? piped_aib_pld_tx_dll_lock_req[i-12] : aib_pld_tx_dll_lock_req[i];
	end
endgenerate

